from playwright.sync_api import sync_playwright,expect
import json
BASE='http://127.0.0.1:4173/'
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);ctx=b.new_context();page=ctx.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 page.goto(BASE+'#/chat',wait_until='networkidle')
 # Actual WebLLM worker-client protocol, with a failed worker response.
 page.evaluate("""async()=>{const {ai}=await import('/ai.js?v=2');const {CreateWebWorkerMLCEngine}=await import('/vendor/engine.js?v=2');const fake={postMessage(msg){queueMicrotask(()=>fake.onmessage({kind:msg.kind==='reload'?'return':'throw',uuid:msg.uuid,content:msg.kind==='reload'?null:'Error: GPU device lost during generation'}))}};const engine=await CreateWebWorkerMLCEngine(fake,'test');ai.engine=engine;ai.status='ready';}""")
 page.locator('#chat-input').fill('Hello!');page.locator('#send-message').click();expect(page.locator('.chat-bubble').last).to_contain_text('GPU device lost');expect(page.locator('#send-message')).to_be_enabled();expect(page.locator('[data-action="retry-chat"]')).to_be_visible()
 print('Real worker protocol failure visible, send button recovered',flush=True)
 page.goto(BASE+'#/create');page.evaluate("""async()=>{const {ai}=await import('/ai.js?v=2');ai.status='ready';ai.engine={chat:{completions:{create:async()=>{throw 'GrammarMatcherInitError: Invalid schema';}}}};}""");page.locator('#lesson-topic').fill('Tea');page.locator('#generate-button').click();expect(page.locator('#generate-status')).to_contain_text('GrammarMatcherInitError');expect(page.locator('#generate-button')).to_be_enabled();print('Lesson worker string error visible and form recovered',flush=True)
 # No worker reply: Stop must end the active request without waiting for a model timeout.
 page.goto(BASE+'#/chat');page.evaluate("""async()=>{const {ai}=await import('/ai.js?v=2');ai.status='ready';ai.engine={chat:{completions:{create:()=>new Promise(()=>{})}},interruptGenerate(){}};}""");page.locator('#chat-input').fill('Are you there?');page.locator('#send-message').click();page.locator('[data-action="stop-generation"]').click();expect(page.locator('#send-message')).to_be_enabled(timeout=6000);expect(page.locator('.chat-bubble').last).to_contain_text('Generation stopped');print('Unresponsive worker Stop settles within grace period',flush=True)
 # A subsequent request recovers instead of staying locked behind the dead worker.
 page.evaluate("""async()=>{const {ai}=await import('/ai.js?v=2');ai.status='ready';ai.engine={chat:{completions:{create:async function*(){yield {choices:[{delta:{content:'Hello again! 你好！'}}]};}}}};}""");page.locator('[data-action="retry-chat"]').last.click();expect(page.locator('.chat-bubble').last).to_contain_text('Hello again!');print('Retry after stopped worker works',flush=True)
 # Complete a typed-schema bilingual story, save and read it.
 page.goto(BASE+'#/create');page.evaluate("""async()=>{const {ai}=await import('/ai.js?v=2');ai.status='ready';ai.engine={chat:{completions:{create:async function*(r){window.sentSchema=JSON.parse(r.response_format.schema);yield {choices:[{delta:{content:JSON.stringify({title:'Tea time',zhTitle:'喝茶时间',lines:[{en:'I like tea.',zh:'我喜欢茶。',pinyin:'Wǒ xǐhuan chá.'},{en:'Tea is warm.',zh:'茶是热的。',pinyin:'Chá shì rè de.'},{en:'My friend is here.',zh:'我的朋友在这里。',pinyin:'Wǒ de péngyou zài zhèlǐ.'},{en:'We drink tea.',zh:'我们喝茶。',pinyin:'Wǒmen hē chá.'}]})}}]};}}}};}""");page.locator('#lesson-topic').fill('Tea');page.locator('#generate-button').click();expect(page.locator('.reader-head h1')).to_have_text('Tea time');assert page.evaluate('sentSchema.properties.lines.minItems')==4;print('Schema-constrained request and bilingual reader pipeline works',flush=True)
 # Startup must not report ready while the mandatory test reply is still pending.
 c=b.new_context();c.add_init_script("Object.defineProperty(navigator,'gpu',{value:{requestAdapter:async()=>({features:new Set(['shader-f16'])})}})")
 c.route('**/vendor/engine.js*',lambda r:r.fulfill(content_type='text/javascript',body="export const CreateWebWorkerMLCEngine=async()=>({chat:{completions:{create:()=>new Promise(()=>{})}},resetChat:async()=>{}}); export const hasModelInCache=async()=>false;"))
 q=c.new_page();q.goto(BASE+'#/create');q.locator('#lesson-topic').fill('A morning walk');q.locator('#generate-button').click();q.locator('[data-action="enable-ai"]').click();expect(q.locator('#ai-status')).to_contain_text('Checking a first reply');assert q.evaluate("async()=>(await import('/ai.js?v=2')).ai.status")=='loading';q.locator('[data-action="cancel-ai"]').click();expect(q.locator('#ai-status')).to_contain_text('cancelled');print('Ready gated on a real reply, setup cancellation works',flush=True)
 # A successful readiness check resumes the lesson the user requested before setup.
 success=b.new_context(service_workers='block');success.add_init_script("Object.defineProperty(navigator,'gpu',{value:{requestAdapter:async()=>({features:new Set(['shader-f16'])})}})")
 success.route('**/vendor/engine.js*',lambda r:r.fulfill(content_type='text/javascript',body="""export const CreateWebWorkerMLCEngine=async()=>({chat:{completions:{create:async r=>r.stream?(async function*(){yield {choices:[{delta:{content:JSON.stringify({title:'A morning walk',zhTitle:'早晨散步',lines:Array.from({length:4},()=>({en:'We walk in the park.',zh:'我们在公园散步。',pinyin:'Wǒmen zài gōngyuán sànbù.'}))})}}]}})():{choices:[{message:{content:'OK'}}]}}},resetChat:async()=>{}});export const hasModelInCache=async()=>false;"""))
 ready=success.new_page();ready.on('pageerror',lambda e:errors.append(str(e)));ready.goto(BASE+'#/create');ready.locator('#lesson-topic').fill('A morning walk');ready.locator('#generate-button').click();ready.locator('[data-action="enable-ai"]').click();expect(ready.locator('.reader-head h1')).to_have_text('A morning walk');assert ready.evaluate("JSON.parse(localStorage.getItem('lingrove-local-ai')).size")=='0.6B';print('Successful setup resumes the requested lesson and remembers the model',flush=True)
 ready.goto(BASE+'#/chat');ready.evaluate("async()=>{(await import('/ai.js?v=2')).cancelAI()}");ready.locator('[data-action="new-phrases"]').click();ready.locator('[data-action="enable-ai"]').click();expect(ready.locator('.chat-bubble.user').last).to_contain_text('Give me three useful');expect(ready.locator('.chat-bubble').last).to_contain_text('A morning walk');expect(ready.locator('#chat-mode-label')).to_contain_text('Ready to chat');expect(ready.locator('.chat-note')).to_contain_text('generated on your device');print('Phrase request continues after model setup, with accurate mode labels',flush=True)
 assert not errors,errors
 print(json.dumps({'console_errors':errors,'passed':9}));b.close()
